package com.overheadadditions;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import java.awt.*;

@Slf4j
@PluginDescriptor(
	name = "Overhead Additions"
)
public class OverheadAdditions extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverheadAdditionsConfig config;

	private String getColorHex(Color color)
	{
		if (color == null) {
			return null;
		}
		return String.format("%02x%02x%02x",
				color.getRed(),
				color.getGreen(),
				color.getBlue());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		String cleanedName = event.getName().replace('\u00A0', ' ');
		String cleanedMessage = event.getMessage().replace('\u00A0', ' ');
		String playerName = cleanedName.replaceAll("<img=\\d+>", "").trim();

		switch (event.getType()) {

			case CLAN_GIM_CHAT:
				if (config.showGIM()) {
					for (Player player : client.getTopLevelWorldView().players()) {
						if (player.getName() != null && player.getName().equalsIgnoreCase(playerName)) {
							if (config.GimChatColor() != null) {
								player.setOverheadText("<col=" + getColorHex(config.GimChatColor()) + ">" + cleanedMessage + "</col>");
							} else player.setOverheadText(cleanedMessage);
						}
						player.setOverheadCycle(Math.max(120, cleanedMessage.length() * config.duration()));
					}
				}
				break;

			case CLAN_GIM_MESSAGE:
				if (config.showGIMMsg()) {
					String playerNameMsg = cleanedMessage.replaceFirst("\\s+has reached.*$", "").replaceFirst("(\\s+received a.*$)", "").trim();
					for (Player player : client.getTopLevelWorldView().players()) {
					if (player.getName() != null && player.getName().equalsIgnoreCase(playerNameMsg)) {
						if (config.GimChatColor() != null) {
							player.setOverheadText("<col=" + getColorHex(config.GimMsgColor()) + ">" + cleanedMessage + "</col>");
						} else player.setOverheadText(cleanedMessage);
					}
					player.setOverheadCycle(Math.max(120, cleanedMessage.length() * config.duration()));
				}
			}
			break;

			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
				if (config.showClan()) {
					for (Player player : client.getTopLevelWorldView().players()) {
						if (player.getName() != null && player.getName().equalsIgnoreCase(playerName)) {
							if (config.clanChatColor() != null) {
								player.setOverheadText("<col=" + getColorHex(config.clanChatColor()) + ">" + cleanedMessage + "</col>");
							} else player.setOverheadText(cleanedMessage);
						}
						player.setOverheadCycle(Math.max(120, cleanedMessage.length() * config.duration()));
					}
				}
				break;

			case CLAN_MESSAGE:
				if (config.showClanMsg()) {
					String playerNameMsg = cleanedMessage.replaceFirst("\\s+has reached.*$", "").replaceFirst("(\\s+received a.*$)", "").trim();
					for (Player player : client.getTopLevelWorldView().players()) {
						if (player.getName() != null && player.getName().equalsIgnoreCase(playerNameMsg)) {
							if (config.GimChatColor() != null) {
								player.setOverheadText("<col=" + getColorHex(config.clanMsgColor()) + ">" + cleanedMessage + "</col>");
							} else player.setOverheadText(cleanedMessage);
						}
						player.setOverheadCycle(Math.max(120, cleanedMessage.length() * config.duration()));
					}
				}
				break;

			case FRIENDSCHAT:
				if (config.showFC()) {
					for (Player player : client.getTopLevelWorldView().players()) {
						if (player.getName() != null && player.getName().equalsIgnoreCase(playerName)) {
							if (config.FCChatColor() != null) {
								player.setOverheadText("<col=" + getColorHex(config.FCChatColor()) + ">" + cleanedMessage + "</col>");
							} else player.setOverheadText(cleanedMessage);
						}
						player.setOverheadCycle(Math.max(120, cleanedMessage.length() * config.duration()));
					}
				}
				break;
		}
	}


	@Provides
	OverheadAdditionsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverheadAdditionsConfig.class);
	}
}

package com.overheadadditions;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup("OverheadAdditions")
public interface OverheadAdditionsConfig extends Config
{
	@ConfigSection(
			name = "Clan",
			description = "Settings for the Clan chat",
			closedByDefault = true,
			position = 1
	)
	String clanSection = "Clan";

	@ConfigSection(
			name = "Friends Chat",
			description = "Settings for the Friends chat",
			closedByDefault = true,
			position = 2
	)
	String FC = "FC";

	@ConfigSection(
			name = "GIM",
			description = "Settings for the Group Ironman chat",
			closedByDefault = true,
			position = 2
	)
	String GIMSection = "GIM";

	@Range(min = 0, max = 20)
	@ConfigItem(
		keyName = "duration",
		name = "Message Duration",
		description = "Overhead message duration is length of message x duration. (default 120 cycles)"
	)
	default int duration()
	{
		return 3;
	}

	@ConfigItem(
			keyName = "clan",
			name = "Show Clan Chat",
			section = clanSection,
			description = "Display Clan Chat above head."
	)default boolean showClan() {return true;}

	@ConfigItem(
			keyName = "clan/msg",
			name = "Show Clan Message",
			section = clanSection,
			description = "Display Clan Messages above head. (Level up, Clog, etc.)"
	)default boolean showClanMsg() {return true;}

	@ConfigItem(
			keyName = "clanChatColor",
			name = "Chat Color",
			section = clanSection,
			description = "Configures the text color for clan chat messages.",
			position = 8
	)
	default Color clanChatColor() {
		return null;
	}

	@ConfigItem(
			keyName = "clanMsgColor",
			name = "Message Color",
			section = clanSection,
			description = "Configures the text color for clan messages. (Level up, Clog, etc.)",
			position = 8
	)
	default Color clanMsgColor() {
		return null;
	}

	@ConfigItem(
			keyName = "friends",
			name = "Show FC",
			section = FC,
			description = "Display Friends Chat above head."
	)default boolean showFC() {return true;}

	@ConfigItem(
			keyName = "friendsChatColor",
			name = "Chat Color",
			section = FC,
			description = "Configures the text color for Friends chat messages.",
			position = 8
	)
	default Color FCChatColor() {
		return null;
	}

	@ConfigItem(
			keyName = "GIM",
			name = "Show GIM Chat",
			section = GIMSection,
			description = "Display Group Iron Chat above head."
	)default boolean showGIM() {return true;}

	@ConfigItem(
			keyName = "GIMMsg",
			name = "Show GIM Message",
			section = GIMSection,
			description = "Display Group Iron Messages above head. (Level up, Clog, etc.)"
	)default boolean showGIMMsg() {return true;}

	@ConfigItem(
			keyName = "clanGimChatColor",
			name = "Chat Color",
			section = GIMSection,
			description = "Configures the text color for GIM chat messages.",
			position = 8
	)
	default Color GimChatColor() {
		return null;
	}

	@ConfigItem(
			keyName = "clanGimMsgColor",
			name = "Message Color",
			section = GIMSection,
			description = "Configures the text color for GIM messages. (Level up, Clog, etc.)",
			position = 8
	)
	default Color GimMsgColor() {
		return null;
	}
}

package com.overheadadditions;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadAdditionsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadAdditions.class);
		RuneLite.main(args);
	}
}
